void moveZeros(List<int> a) {
  var w = 0;
  for (final x in a) {
    if (x != 0) a[w++] = x;
  }
  while (w < a.length) {
    a[w++] = 0;
  }
}

void main() {
  final a = [0, 4, 0, 5, 6];
  moveZeros(a);
  print(a);
}
```

